 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    horizontal = next((r for r in range(h) if all(x == 2 for x in grid[r])), None)
    vertical = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    comps, seen = [], set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            comps.append((color, cells))

    out = [[0] * w for _ in range(h)]
    if horizontal is not None:
        out[horizontal] = list(grid[horizontal])
        occupied = {(horizontal, c) for c in range(w)}
        # Gravity is away from the marker row (downward for the demonstrated top wall).
        comps.sort(key=lambda obj: max(r for r, _ in obj[1]), reverse=True)
        for color, cells in comps:
            shift = 0
            while True:
                nxt = [(r + shift + 1, c) for r, c in cells]
                if any(r >= h or (r, c) in occupied for r, c in nxt):
                    break
                shift += 1
            for r, c in cells:
                out[r + shift][c] = color
                occupied.add((r + shift, c))
        return out

    for r in range(h):
        out[r][vertical] = 2
    # Components shift toward the vertical marker, retaining their row coordinates.
    comps.sort(key=lambda obj: min(c for _, c in obj[1]))
    occupied = {(r, vertical) for r in range(h)}
    for color, cells in comps:
        shift = 0
        while True:
            nxt = [(r, c + shift - 1) for r, c in cells]
            if any(c < 0 or (r, c) in occupied for r, c in nxt):
                break
            shift -= 1
        for r, c in cells:
            out[r][c + shift] = color
            occupied.add((r, c + shift))
    return out


